<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';
import AppShell from '../Components/AppShell.vue';
import Errors from '../Components/Errors.vue';
import type { Account, Identifier } from '../types';
defineProps<{accounts:Account[];institutions:string[]}>();
const editing = ref<number|null>(null);
const form=useForm({institution:'Bank of America',nickname:'',card_network:'' as string|null,identifiers:[] as Identifier[]});
function edit(a:Account) {editing.value=a.id;form.clearErrors();form.institution=a.institution;form.nickname=a.nickname;form.card_network=a.card_network;form.identifiers=a.identifiers.map(i=>({kind:i.kind,last_four:i.last_four,device_label:i.device_label}));document.getElementById('account-editor')?.scrollIntoView({behavior:'smooth'});}
function reset() {editing.value=null;form.reset();form.clearErrors();}
function save() { const options={preserveScroll:true,onSuccess:reset}; if(editing.value)form.patch(`/accounts/${editing.value}`,options);else form.post('/accounts',options); }
</script>
<template><AppShell><Head title="Accounts"/><section class="page-heading"><div><p class="eyebrow">A PLACE FOR EVERY PURCHASE</p><h1>Your payment accounts.</h1><p class="muted">Names you recognize. Just the last four digits.</p></div></section><div class="accounts-grid"><section><div v-if="!accounts.length" class="empty-state compact"><span class="empty-icon">▱</span><h2>Start with your everyday card.</h2><p>Add an account when you’re ready. You can scan receipts without one.</p></div><article v-for="a in accounts" :key="a.id" class="account-card"><div class="section-heading"><span class="eyebrow">{{ a.institution }}</span><button class="text-button" @click="edit(a)">Edit ↗</button></div><h2>{{ a.nickname }}</h2><p class="muted">{{ a.card_network || 'Card network not specified' }}</p><div v-for="(i,index) in a.identifiers" :key="index" class="identifier-row"><span>{{ i.kind === 'wallet' ? 'Device / Wallet' : 'Physical card' }} <small v-if="i.device_label">· {{ i.device_label }}</small></span><strong>•••• {{ i.last_four }}</strong></div><small v-if="!a.identifiers.length" class="muted">No identifiers added.</small></article><div class="privacy-note"><strong>No bank connection required.</strong><p>Account labels help match receipts. Bank of America, Capital One, Chime, and Synchrony are supported as labels. For Synchrony, use nicknames such as Sam’s Club, Walmart, or Amazon. No card product or Wallet eligibility is assumed.</p></div></section><form id="account-editor" @submit.prevent="save" class="edit-panel"><div class="section-heading"><h2>{{ editing ? 'Edit account' : 'Add an account' }}</h2><button v-if="editing" type="button" class="text-button" @click="reset">Cancel</button></div><Errors :errors="form.errors"/><label>Institution<select v-model="form.institution"><option v-for="i in institutions" :key="i">{{ i }}</option></select></label><label>Nickname<input v-model="form.nickname" placeholder="e.g. Everyday card, Sam’s Club" required maxlength="100"/></label><label>Card network <span class="muted">(optional)</span><input v-model="form.card_network" placeholder="e.g. Visa, Mastercard" maxlength="30"/></label><div class="section-heading item-heading"><h3>Card identifiers</h3><button type="button" class="text-button" @click="form.identifiers.push({kind:'physical',last_four:'',device_label:null})">+ Add</button></div><p class="muted small">Your physical card and device Wallet may show different last four digits. Add either or both; a suffix may match multiple accounts.</p><div v-for="(i,index) in form.identifiers" :key="index" class="identifier-editor"><label>Type<select v-model="i.kind"><option value="physical">Physical card</option><option value="wallet">Device / Wallet</option></select></label><label>Last four digits<input v-model="i.last_four" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required placeholder="1234"/></label><label>Device label <span class="muted">(optional)</span><input v-model="i.device_label" maxlength="100" placeholder="e.g. My iPhone"/></label><button type="button" class="text-button" @click="form.identifiers.splice(index,1)">Remove identifier</button></div><p class="privacy-note small">Never enter a full card number, CVV, or banking credentials.</p><button class="button primary full" :disabled="form.processing">{{ form.processing ? 'Saving…' : 'Save account' }} <span>→</span></button></form></div></AppShell></template>
